create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text, target_score int default 1200, created_at timestamptz default now());
create table public.skills (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, area text not null check (area in ('math','reading_writing')), prerequisite_id uuid references public.skills);
create table public.questions (id uuid primary key default gen_random_uuid(), skill_id uuid not null references public.skills, difficulty int not null check (difficulty between 1 and 3), prompt text not null, options jsonb not null, correct_index int not null, explanation text not null, tip text not null, mistake_tag text);
create table public.diagnostic_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, area text not null, started_at timestamptz default now(), completed_at timestamptz);
create table public.practice_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, started_at timestamptz default now(), completed_at timestamptz);
create table public.answers (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, question_id uuid not null references public.questions, diagnostic_id uuid references public.diagnostic_attempts, session_id uuid references public.practice_sessions, selected_index int not null, is_correct boolean not null, response_ms int, created_at timestamptz default now());
create table public.mastery_scores (user_id uuid references public.profiles, skill_id uuid references public.skills, score int not null check (score between 0 and 100), attempts int default 0, updated_at timestamptz default now(), primary key (user_id, skill_id));
create table public.study_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, week_start date not null, target_minutes int not null, created_at timestamptz default now());
create table public.study_tasks (id uuid primary key default gen_random_uuid(), plan_id uuid not null references public.study_plans on delete cascade, skill_id uuid references public.skills, due_date date not null, question_count int, minutes int, task_type text not null, completed_at timestamptz);
create table public.mistake_patterns (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, skill_id uuid references public.skills, pattern text not null, occurrences int default 1, last_seen_at timestamptz default now(), resolved_at timestamptz);
create table public.agent_decisions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, decision_type text not null, reason text not null, metadata jsonb default '{}', created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.diagnostic_attempts enable row level security; alter table public.practice_sessions enable row level security; alter table public.answers enable row level security; alter table public.mastery_scores enable row level security; alter table public.study_plans enable row level security; alter table public.study_tasks enable row level security; alter table public.mistake_patterns enable row level security; alter table public.agent_decisions enable row level security;
alter table public.skills enable row level security; alter table public.questions enable row level security;
create policy "profiles_own" on public.profiles for all using (auth.uid() = id) with check (auth.uid() = id);
create policy "attempts_own" on public.diagnostic_attempts for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "sessions_own" on public.practice_sessions for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "answers_own" on public.answers for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "mastery_own" on public.mastery_scores for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "plans_own" on public.study_plans for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "tasks_own" on public.study_tasks for all using (exists (select 1 from public.study_plans p where p.id = plan_id and p.user_id = auth.uid())) with check (exists (select 1 from public.study_plans p where p.id = plan_id and p.user_id = auth.uid()));
create policy "mistakes_own" on public.mistake_patterns for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "decisions_own" on public.agent_decisions for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "skills_read" on public.skills for select using (true); create policy "questions_read" on public.questions for select using (true);
